/**
 * Field cards for an event automation's instruction, built from the catalog payload schema.
 *
 * Each card is one event field the user can drop into the instruction as a pill. The pill is
 * stored as a selector into the dispatcher's event context: `$.event.attributes.<key>`.
 */
import {humanizeActionKey} from "@agenta/shared/utils"

import {selectorPath} from "./selectorPreview"

const EVENT_ATTRIBUTES = "$.event.attributes"

export interface EventFieldCard {
    key: string
    selector: string
    label: string
    /** The provider's own description, or null when the schema has none. */
    description: string | null
}

/** A run of cards. `label` is null for top-level fields, else the object's humanized name. */
export interface EventFieldGroup {
    key: string
    label: string | null
    cards: EventFieldCard[]
}

/** `["data", "createdBy"]` → "Data created by". Splits camelCase, then `humanizeActionKey`. */
export function fieldLabel(path: string[]): string {
    const words = path.map((segment) => segment.replace(/([a-z0-9])([A-Z])/g, "$1_$2")).join("_")
    return humanizeActionKey(words)
}

function selectorStep(key: string): string {
    return /^[A-Za-z0-9_]+$/.test(key) ? `.${key}` : `[${JSON.stringify(key)}]`
}

/** The selector for an event field path, in bracket form where a key needs it. */
export function eventFieldSelector(path: string[]): string {
    return EVENT_ATTRIBUTES + path.map(selectorStep).join("")
}

/** A pill's label: the card's label when known, else the field path made readable. */
export function selectorLabel(selector: string, labels: Record<string, string>): string {
    const known = labels[selector]
    if (known) return known
    const path = selectorPath(selector)
    const prefix = ["event", "attributes"]
    if (!path) return selector
    const field = prefix.every((key, i) => path[i] === key) ? path.slice(2) : path
    return field.length ? fieldLabel(field) : selector
}

function propertiesOf(schema: unknown): [string, Record<string, unknown>][] {
    if (!schema || typeof schema !== "object") return []
    const properties = (schema as {properties?: unknown}).properties
    if (!properties || typeof properties !== "object" || Array.isArray(properties)) return []
    return Object.entries(properties as Record<string, unknown>).map(([key, value]) => [
        key,
        value && typeof value === "object" ? (value as Record<string, unknown>) : {},
    ])
}

function card(path: string[], property: Record<string, unknown>): EventFieldCard {
    const description =
        typeof property.description === "string" && property.description.trim()
            ? property.description.trim()
            : null
    return {
        key: path.join("."),
        selector: eventFieldSelector(path),
        label: fieldLabel(path),
        description,
    }
}

/**
 * One card per property of `payload.properties`, in schema order. An object with its own
 * `properties` is a group with one card per child; deeper objects and arrays are one card.
 */
export function eventFieldsFromSchema(payloadSchema: unknown): EventFieldGroup[] {
    const groups: EventFieldGroup[] = []
    for (const [key, property] of propertiesOf(payloadSchema)) {
        const children = property.type === "object" ? propertiesOf(property) : []
        if (children.length) {
            groups.push({
                key,
                label: fieldLabel([key]),
                cards: children.map(([child, value]) => card([key, child], value)),
            })
            continue
        }
        const last = groups[groups.length - 1]
        if (last && last.label === null) last.cards.push(card([key], property))
        else groups.push({key, label: null, cards: [card([key], property)]})
    }
    return groups
}

/** Selector → label for every card, the lookup the preview and the pills read. */
export function eventFieldLabels(groups: EventFieldGroup[]): Record<string, string> {
    return Object.fromEntries(
        groups.flatMap((group) => group.cards.map((c) => [c.selector, c.label] as const)),
    )
}
/**
 * Token-template ⇆ `inputs_fields` for the subscription "What the agent gets" composer.
 *
 * A non-technical user writes a message and drops in event fields as `{{path}}` tokens.
 * We compile that to a backend-resolvable `inputs_fields`: a chat user message (or the
 * completion agent's primary input) whose `content` is EITHER a single string (one literal
 * or one `$.selector`) OR an array of text parts — literal runs kept, `$.selector` runs
 * resolved leaf-by-leaf at delivery by `resolve_target_fields`. No backend change: it's the
 * same whole-string-or-literal leaf resolution, just structured as parts.
 *
 * Display ≠ storage: the editor shows `{{event.attributes.body}}`; we store
 * `{type:"text", text:"$.event.attributes.body"}`. Other keys of the mapping are kept.
 */

export interface TemplateSegment {
    literal?: string
    selector?: string
}

// `{{ path }}` tokens. The inner path is a JSONPath/Pointer or a dot path (→ `$.path`).
// No \s* around the capture (ReDoS-ambiguous with [^{}]); `tokenToSelector` trims instead.
const TOKEN_RE = /\{\{([^{}]+)\}\}/g

function tokenToSelector(token: string): string {
    const t = token.trim()
    if (!t) return ""
    if (t.startsWith("$") || t.startsWith("/")) return t
    return `$.${t}`
}

function selectorToToken(selector: string): string {
    if (selector === "$") return "{{$}}"
    if (selector.startsWith("$.")) return `{{${selector.slice(2)}}}`
    return `{{${selector}}}`
}

/** Split a template string into literal + selector segments (in order). */
export function splitTemplate(template: string): TemplateSegment[] {
    const segments: TemplateSegment[] = []
    let last = 0
    let m: RegExpExecArray | null
    TOKEN_RE.lastIndex = 0
    while ((m = TOKEN_RE.exec(template)) !== null) {
        if (m.index > last) segments.push({literal: template.slice(last, m.index)})
        const selector = tokenToSelector(m[1])
        if (selector) segments.push({selector})
        last = m.index + m[0].length
    }
    if (last < template.length) segments.push({literal: template.slice(last)})
    return segments
}

// Segments → a message `content`: "" when empty, a bare string for one literal (or one selector
// when `pillsAsParts` is off), else an array of resolvable text parts.
function segmentsToContent(
    segments: TemplateSegment[],
    pillsAsParts: boolean,
): string | {type: "text"; text: string}[] {
    const nonEmpty = segments.filter((s) => (s.selector ?? s.literal ?? "") !== "")
    if (nonEmpty.length === 0) return ""
    const only = nonEmpty.length === 1 ? nonEmpty[0] : null
    if (only && (only.literal !== undefined || !pillsAsParts))
        return only.selector ?? only.literal ?? ""
    return nonEmpty.map((s) => ({type: "text" as const, text: s.selector ?? s.literal ?? ""}))
}

/** The selectors a template uses, in order; the field cards mark these as used. */
export function templateSelectors(template: string): string[] {
    return splitTemplate(template).flatMap((s) => (s.selector ? [s.selector] : []))
}

function parseObject(inputsText: string): Record<string, unknown> | null {
    try {
        const parsed: unknown = inputsText.trim() ? JSON.parse(inputsText) : {}
        return parsed && typeof parsed === "object" && !Array.isArray(parsed)
            ? (parsed as Record<string, unknown>)
            : null
    } catch {
        return null
    }
}

// A `messages` payload edits as chat even when the schema says completion, like `messageInputs`.
function messageKey(obj: Record<string, unknown>, isChat: boolean, primaryKey: string): string {
    return isChat || Array.isArray(obj.messages) ? "messages" : primaryKey
}

/**
 * Write a token template into `inputs_fields`, returning the serialized JSON. Only the message
 * key changes: chat agents get one `messages` user message, completion agents the primary key.
 * In `messages`, a pill is always a text part, even alone. Every other key is kept. An empty
 * template removes the message key.
 */
export function compileMessageTemplate(
    inputsText: string,
    template: string,
    isChat: boolean,
    primaryKey: string,
): string {
    const obj = parseObject(inputsText) ?? {}
    const key = messageKey(obj, isChat, primaryKey)
    // A bare selector on an array field would become the message parts; a text part keeps it text.
    const content = template.trim()
        ? segmentsToContent(splitTemplate(template), key === "messages")
        : ""
    if (content === "") delete obj[key]
    else obj[key] = key === "messages" ? [{role: "user", content}] : content
    return Object.keys(obj).length ? JSON.stringify(obj, null, 2) : "{}"
}

// A content value the composer can REPRODUCE: a plain string, or an array of strictly
// `{type:"text", text}` parts (what `segmentsToContent` emits). Returns the template, or null
// when not representable (an image/audio part, or a malformed object) so callers don't show —
// then silently collapse — a payload they can't round-trip.
function contentToTemplate(content: unknown): string | null {
    if (typeof content === "string") {
        return content.startsWith("$") || content.startsWith("/")
            ? selectorToToken(content)
            : content
    }
    if (Array.isArray(content)) {
        const parts: string[] = []
        for (const p of content) {
            if (
                !p ||
                typeof p !== "object" ||
                (p as {type?: unknown}).type !== "text" ||
                typeof (p as {text?: unknown}).text !== "string"
            ) {
                return null
            }
            const text = (p as {text: string}).text
            parts.push(text.startsWith("$") || text.startsWith("/") ? selectorToToken(text) : text)
        }
        return parts.join("")
    }
    return null
}

/**
 * Read `inputs_fields` (serialized JSON) back into a token template for the editor. Keys other
 * than the message key are ignored. Returns "" when there is no message yet, and null when the
 * composer cannot show the mapping (several messages, a non-user message, a non-text part).
 */
export function parseMessageTemplate(
    inputsText: string,
    isChat: boolean,
    primaryKey: string,
): string | null {
    const obj = parseObject(inputsText)
    if (!obj) return null
    const key = messageKey(obj, isChat, primaryKey)
    if (!(key in obj)) return ""
    if (key !== "messages") return contentToTemplate(obj[key])
    const messages = obj.messages
    if (!Array.isArray(messages) || messages.length !== 1) return null
    const message = messages[0]
    if (!message || typeof message !== "object" || (message as {role?: string}).role !== "user")
        return null
    return contentToTemplate((message as {content?: unknown}).content)
}

/**
 * Move the template to a new agent input shape once the bound agent resolves. The old key is
 * removed, other keys are kept, and a mapping the composer cannot show is returned unchanged.
 */
export function remapMessageTemplate(
    inputsText: string,
    prev: {isChat: boolean; primaryKey: string},
    next: {isChat: boolean; primaryKey: string},
): string {
    const template = parseMessageTemplate(inputsText, prev.isChat, prev.primaryKey)
    if (!template) return inputsText
    const obj = parseObject(inputsText) ?? {}
    delete obj[messageKey(obj, prev.isChat, prev.primaryKey)]
    return compileMessageTemplate(JSON.stringify(obj), template, next.isChat, next.primaryKey)
}
/**
 * The text the agent gets for an event automation, built the way the dispatcher builds it.
 *
 * The preview and Run now both call `renderMessagePreview`, so Run now sends what the preview
 * shows. `formatEventText` and `eventValueText` mirror the backend (`core/triggers/utils.py`).
 */
import {selectorLabel} from "./eventFields"
import {splitTemplate} from "./eventMessageTemplate"
import {resolveSelectorPreview} from "./selectorPreview"

/** A resolved pill value as text: a string unchanged, null or absent empty, else compact JSON. */
export function eventValueText(value: unknown): string {
    if (typeof value === "string") return value
    if (value === null || value === undefined) return ""
    return JSON.stringify(value) ?? ""
}

/** The event block added to the agent's message, starting with a blank line. */
export function formatEventText(eventType: unknown, attributes: unknown): string {
    const header =
        typeof eventType === "string" && eventType ? `Event data (${eventType}):` : "Event data:"
    return `\n\n${header}\n\`\`\`json\n${JSON.stringify(attributes, null, 2)}\n\`\`\``
}

/**
 * The whole message for a template. With an event, pills take its values; without one, each
 * pill reads as its label in square brackets. With `includeEvent` and event attributes, the
 * event block is added at the end.
 */
export function renderMessagePreview(
    template: string,
    event: Record<string, unknown> | null,
    labels: Record<string, string>,
    includeEvent: boolean,
): string {
    const text = splitTemplate(template)
        .map((segment) => {
            if (segment.selector === undefined) return segment.literal ?? ""
            if (event) return eventValueText(resolveSelectorPreview(segment.selector, {event}))
            return `[${selectorLabel(segment.selector, labels)}]`
        })
        .join("")
    if (!includeEvent || !event || event.attributes == null) return text
    const block = formatEventText(event.event_type, event.attributes)
    // An empty template saves as `{}`, where the dispatcher sends the block alone.
    return template.trim() ? text + block : block.replace(/^\n\n/, "")
}

import type {Automation} from "@agenta/automation-ui"
import {
    getScheduleMessagePreview,
    latestDeliveryEvent,
    parseMessageTemplate,
    queryTriggerDeliveries,
    renderMessagePreview,
    type TriggerSubscription,
} from "@agenta/entities/gatewayTrigger"

/**
 * The text Run now sends: for an event automation, the same text the instruction preview shows,
 * with pills filled from the newest recorded event. Rejects when the deliveries call fails, so
 * the caller can refuse to start rather than send a guess.
 */
export async function runNowText(
    automation: Automation,
    queryDeliveries: typeof queryTriggerDeliveries = queryTriggerDeliveries,
): Promise<string> {
    const inputs = automation.raw.data?.inputs_fields
    const today = getScheduleMessagePreview(inputs).trim()
    if (automation.kind !== "event" || !inputs || typeof inputs !== "object") return today
    // Run now has no agent schema; only a `messages` mapping reads the same without one.
    if (!Array.isArray((inputs as Record<string, unknown>).messages)) return today
    const template = parseMessageTemplate(JSON.stringify(inputs), true, "messages")
    if (template === null) return today

    const {deliveries} = await queryDeliveries({subscription_id: automation.id})
    const includeEvent = (automation.raw as TriggerSubscription).data?.include_event ?? true
    // The card labels are `fieldLabel` of the path, which `selectorLabel` falls back to.
    return renderMessagePreview(template, latestDeliveryEvent(deliveries), {}, includeEvent).trim()
}
/** The token composer's contenteditable surface: `{{selector}}` segments render as chips. */
import {useCallback, useEffect, useRef, useState} from "react"

import {splitTemplate} from "@agenta/entities/gatewayTrigger"

// Pill-style composer: a contenteditable where `{{token}}` segments render as inline,
// atomic chips (friendly labels). Source of truth is the template string; it re-renders
// the DOM only when `value` changes from outside (not on the user's own keystrokes).
export function PillEditor({
    value,
    onChange,
    placeholder,
    insertApi,
    labelFor,
    disabled,
}: {
    value: string
    onChange: (next: string) => void
    placeholder?: string
    /** `insert(selector)` puts a pill at the caret, or at the end when the box is not focused. */
    insertApi?: React.MutableRefObject<{insert: (selector: string) => void} | null>
    /** The label a pill shows for its selector. */
    labelFor: (selector: string) => string
    disabled?: boolean
}) {
    const ref = useRef<HTMLDivElement>(null)
    const lastSerialized = useRef<string>("")
    const [empty, setEmpty] = useState(!value.trim())

    const makePill = useCallback(
        (selector: string) => {
            const inner = selector.startsWith("$.") ? selector.slice(2) : selector
            const label = labelFor(selector)
            const span = document.createElement("span")
            span.dataset.token = REDACTED
            span.contentEditable = "false"
            span.className =
                "mx-0.5 inline-flex select-none items-center gap-1 rounded-md border border-solid border-border bg-muted px-1.5 py-0.5 text-xs font-medium text-foreground"
            span.appendChild(document.createTextNode(label))
            const remove = document.createElement("button")
            remove.type = "button"
            remove.dataset.remove = ""
            remove.ariaLabel = `Remove ${label}`
            remove.className =
                "cursor-pointer border-0 bg-transparent p-0 text-xs leading-none text-inherit opacity-70 hover:opacity-100"
            remove.textContent = "×"
            span.appendChild(remove)
            return span
        },
        [labelFor],
    )

    const render = useCallback(
        (tpl: string) => {
            const el = ref.current
            if (!el) return
            el.innerHTML = ""
            for (const seg of splitTemplate(tpl)) {
                if (seg.literal != null) {
                    seg.literal.split("\n").forEach((part, i) => {
                        if (i > 0) el.appendChild(document.createElement("br"))
                        if (part) el.appendChild(document.createTextNode(part))
                    })
                } else if (seg.selector != null) {
                    el.appendChild(makePill(seg.selector))
                }
            }
        },
        [makePill],
    )

    const serialize = useCallback((el: HTMLElement): string => {
        let out = ""
        el.childNodes.forEach((node) => {
            if (node.nodeType === Node.TEXT_NODE) out += node.textContent ?? ""
            else if (node instanceof HTMLElement) {
                if (node.dataset.token != null) out += `{{${node.dataset.token}}}`
                else if (node.tagName === "BR") out += "\n"
                else out += "\n" + serialize(node)
            }
        })
        return out
    }, [])

    const renderedWith = useRef(render)
    useEffect(() => {
        // New labels (the event schema landed) redraw the pills too.
        if (value !== lastSerialized.current || render !== renderedWith.current) {
            render(value)
            renderedWith.current = render
            lastSerialized.current = value
            setEmpty(!value.trim())
        }
    }, [value, render])

    const commit = useCallback(() => {
        const el = ref.current
        if (!el) return
        const next = serialize(el)
        lastSerialized.current = next
        setEmpty(!next.trim())
        onChange(next)
    }, [serialize, onChange])

    // Insert plain text at the caret, newlines as <br> (what `serialize` reads back).
    const insertText = useCallback((text: string) => {
        const sel = window.getSelection()
        if (!sel?.rangeCount) return
        const range = sel.getRangeAt(0)
        range.deleteContents()
        const frag = document.createDocumentFragment()
        text.replace(/\r\n?/g, "\n")
            .split("\n")
            .forEach((line, i) => {
                if (i > 0) frag.appendChild(document.createElement("br"))
                if (line) frag.appendChild(document.createTextNode(line))
            })
        const last = frag.lastChild
        range.insertNode(frag)
        if (!last) return
        range.setStartAfter(last)
        range.collapse(true)
        sel.removeAllRanges()
        sel.addRange(range)
    }, [])

    // The template is plain text plus atomic pills; pasted markup would both corrupt
    // `serialize` and inject live nodes into the editor.
    const onPaste = useCallback(
        (e: React.ClipboardEvent) => {
            e.preventDefault()
            insertText(e.clipboardData.getData("text/plain"))
            commit()
        },
        [insertText, commit],
    )

    useEffect(() => {
        if (!insertApi) return
        insertApi.current = {
            insert: (selector: string) => {
                const el = ref.current
                if (!el) return
                el.focus()
                const sel = window.getSelection()
                const pill = makePill(selector)
                const space = document.createTextNode(" ")
                let range: Range
                if (sel?.rangeCount && el.contains(sel.anchorNode)) {
                    range = sel.getRangeAt(0)
                    range.deleteContents()
                } else {
                    range = document.createRange()
                    range.selectNodeContents(el)
                    range.collapse(false)
                }
                range.insertNode(space)
                range.insertNode(pill)
                range.setStartAfter(space)
                range.collapse(true)
                sel?.removeAllRanges()
                sel?.addRange(range)
                commit()
            },
        }
        return () => {
            insertApi.current = null
        }
    }, [insertApi, makePill, commit])

    // The pill's × removes the pill, like Backspace does.
    const onClick = (e: React.MouseEvent) => {
        const remove = (e.target as HTMLElement).closest("[data-remove]")
        if (!remove || disabled) return
        e.preventDefault()
        remove.parentElement?.remove()
        commit()
    }

    const onKeyDown = (e: React.KeyboardEvent) => {
        if (e.key !== "Enter") return
        e.preventDefault()
        insertText("\n")
        commit()
    }

    return (
        <div className="relative">
            <div
                ref={ref}
                contentEditable={!disabled}
                suppressContentEditableWarning
                role="textbox"
                aria-multiline="true"
                aria-disabled={disabled}
                onInput={commit}
                onPaste={onPaste}
                onKeyDown={onKeyDown}
                onClick={onClick}
                className="box-border max-h-[280px] min-h-[88px] w-full overflow-y-auto whitespace-pre-wrap break-words rounded-lg border border-solid border-[var(--ag-colorBorder)] bg-[var(--ag-colorBgContainer)] px-3 py-2 text-base leading-relaxed text-foreground outline-none focus:border-[var(--ag-colorPrimary)] aria-disabled:cursor-not-allowed aria-disabled:opacity-60 md:text-sm"
            />
            {empty && placeholder && (
                <div className="pointer-events-none absolute left-3 top-2 text-base text-[var(--ag-colorTextPlaceholder)] md:text-sm">
                    {placeholder}
                </div>
            )}
        </div>
    )
}
/** The event automation's instruction: text plus event-field pills, over `inputs_fields`. */
import {useCallback} from "react"

import {
    compileMessageTemplate,
    parseMessageTemplate,
    selectorLabel,
} from "@agenta/entities/gatewayTrigger"

import {PillEditor} from "./PillEditor"

// The schedule composer's sibling for event automations. It keeps every key of the mapping
// except the message; a mapping it cannot show keeps the warning `MessageComposer` gives.
export function EventMessageComposer({
    inputsText,
    onChange,
    isChat,
    primaryKey,
    labels,
    insertApi,
    disabled,
}: {
    inputsText: string
    onChange: (next: string) => void
    isChat: boolean
    primaryKey: string
    /** Selector → field label, from the event's field cards. */
    labels: Record<string, string>
    insertApi?: React.MutableRefObject<{insert: (selector: string) => void} | null>
    disabled?: boolean
}) {
    const template = parseMessageTemplate(inputsText, isChat, primaryKey)
    const labelFor = useCallback((selector: string) => selectorLabel(selector, labels), [labels])

    return (
        <div className="flex flex-col gap-1.5">
            <PillEditor
                value={template ?? ""}
                onChange={(next) =>
                    onChange(compileMessageTemplate(inputsText, next, isChat, primaryKey))
                }
                insertApi={insertApi}
                labelFor={labelFor}
                disabled={disabled}
            />
            <span
                className={`text-xs leading-snug ${
                    template === null
                        ? "text-[var(--ag-colorWarningText)]"
                        : "text-[var(--ag-colorTextDescription)]"
                }`}
            >
                {template === null
                    ? "This schedule sends a richer set of inputs than one message — typing here replaces them."
                    : "Sent to the agent each time this event happens. Fields fill in with the real values."}
            </span>
        </div>
    )
}

