/** Radix tooltip in antd's ergonomic shape (`title` + child). No title → just the child. */
export const Tip = ({
    title,
    side,
    children,
}: {
    title: ReactNode
    side?: "top" | "right" | "bottom" | "left"
    children: ReactNode
}) => {
    if (title == null) return <>{children}</>
